var SA = window.SA || (window.SA = {});

SA.content = {
  distribuzioni: {
    obiettivi: ['Distinguere densità, probabilità puntuali e funzione di ripartizione', 'Calcolare P(a < X ≤ b) come differenza di ripartizioni', 'Riconoscere quando valore atteso e varianza non esistono', 'Collegare le leggi tra loro: casi particolari, trasformazioni, limiti'],
    valutiamo: [['Forma della legge', 'la curva nera (teoria) contro l’istogramma blu (dati generati)'], ['Probabilità di un intervallo', 'l’area arancione sotto la densità e il salto F(b) − F(a) nel grafico in basso'], ['Distanza fra dati e modello', 'sup|F̂ − F|: deve stare quasi sempre dentro la banda DKW'], ['Momenti', 'media, varianza e mediana teoriche contro quelle del campione']],
    tabella: 'Colonna Teoria: valori esatti della legge scelta. Colonna Simulazione: gli stessi indici calcolati sulle osservazioni generate finora. La differenza è variabilità Monte Carlo e si riduce come 1/√N; il simbolo † segnala un valore empirico che non converge perché il momento teorico non esiste.',
    esempio: '<p><strong>Esempio svolto.</strong> X ~ Gamma(k = 2, λ = 1). Valore atteso k/λ = 2, varianza k/λ² = 2. La probabilità P(1 < X ≤ 3) si ottiene da F(x) = 1 − e<sup>−x</sup>(1 + x): F(3) − F(1) = (1 − 4e<sup>−3</sup>) − (1 − 2e<sup>−1</sup>) = 2e<sup>−1</sup> − 4e<sup>−3</sup> ≈ 0,5366. Imposta a = 1 e b = 3 e verifica il valore nel grafico della ripartizione.</p>',
    errori: ['Leggere f(x) come una probabilità: per una legge continua P(X = x) = 0 e f(x) può superare 1', 'Dimenticare quali estremi sono inclusi nelle leggi discrete: P(X ≤ b) ≠ P(X < b)', 'Calcolare la media campionaria di dati Cauchy e interpretarla come stima di un valore atteso che non esiste', 'Confondere la parametrizzazione: in R rexp usa il tasso λ, non la media 1/λ'],
    avanzato: '<h3>Famiglie di posizione e scala</h3><p>Se Z ha densità f₀, allora X = μ + σZ ha densità f₀((x − μ)/σ)/σ: Normale, Cauchy, Laplace, Logistica sono famiglie di questo tipo. Quantili e momenti si trasformano linearmente, e gli stimatori “equivarianti” rispettano la trasformazione.</p><h3>Famiglia esponenziale</h3><p>Molte leggi del catalogo (Bernoulli, Binomiale con n noto, Poisson, Geometrica, Normale, Gamma, Beta) hanno densità della forma h(x) exp{η(θ)T(x) − A(θ)}. Ne seguono le proprietà che rivedremo nei laboratori di inferenza: statistiche sufficienti di dimensione fissa, E T(X) = A′, stimatori di massima verosimiglianza che uguagliano media teorica ed empirica di T.</p><h3>Funzione generatrice dei momenti e trasformazioni</h3><p>M(t) = E e<sup>tX</sup>, quando esiste in un intorno di 0, determina la legge. È lo strumento più rapido per dimostrare i legami della mappa: per esempio la somma di k esponenziali indipendenti ha M(t) = (λ/(λ − t))<sup>k</sup>, che è la funzione generatrice della Gamma(k, λ).</p>',
    esercizi: [['Per X ~ Esponenziale(λ) dimostra che P(X > s + t | X > s) = P(X > t). Che cosa significa per un tempo di attesa?', 'P(X > s + t)/P(X > s) = e<sup>−λ(s+t)</sup>/e<sup>−λs</sup> = e<sup>−λt</sup>. Assenza di memoria: aver già atteso s non cambia la legge dell’attesa residua.'], ['Se U ~ U(0, 1), qual è la legge di −log(U)/λ? Verificalo nel laboratorio 03.', 'P(−log U/λ ≤ x) = P(U ≥ e<sup>−λx</sup>) = 1 − e<sup>−λx</sup>: Esponenziale(λ).'], ['Con N = 1000 osservazioni, quanto vale il raggio della banda DKW al 95%? Quante osservazioni servono per dimezzarlo?', 'ε = √(log 40/2000) ≈ 0,043. Il raggio scala come 1/√N: per dimezzarlo servono 4000 osservazioni.']],
    riferimenti: ['Casella G., Berger R. L. (2002). Statistical Inference, 2ª ed. Duxbury, capp. 2–3.', 'Johnson N. L., Kotz S., Balakrishnan N. (1994–1995). Continuous Univariate Distributions, voll. 1–2. Wiley.', 'Massart P. (1990). The tight constant in the Dvoretzky–Kiefer–Wolfowitz inequality. Annals of Probability 18, 1269–1283.', 'Leemis L. M., McQueston J. T. (2008). Univariate distribution relationships. The American Statistician 62, 45–53.']
  },
  bivariata: {
    obiettivi: ['Leggere una legge congiunta attraverso marginali e condizionate', 'Interpretare covarianza e correlazione come misure di dipendenza lineare', 'Riconoscere dipendenze non lineari con correlazione nulla', 'Comprendere la regressione come media condizionata'],
    valutiamo: [['Dipendenza lineare', 'la correlazione campionaria r contro ρ teorico'], ['Dipendenza non lineare', 'la correlazione tra X² e Y nel modello quadratico'], ['Legge condizionata', 'l’istogramma arancione dei punti nella striscia contro la densità teorica di Y | X = x₀'], ['Marginali', 'gli istogrammi ai bordi: non cambiano al variare di ρ']],
    tabella: 'Le righe 1–2 confrontano le correlazioni teoriche con quelle stimate su tutte le coppie. Le righe 3–4 usano solo i punti nella striscia attorno a x₀: approssimano la legge condizionata, con una distorsione che cresce con l’ampiezza h e una variabilità che cresce se h è piccolo.',
    esempio: '<p><strong>Esempio svolto.</strong> Con ρ = 0,6 e x₀ = 1, la legge condizionata è N(0,6; 1 − 0,36) = N(0,6; 0,64): media 0,6 e deviazione standard 0,8. Conoscere X riduce la varianza di Y del 36% (= ρ²). È esattamente la quota di varianza “spiegata” dalla regressione.</p>',
    errori: ['Concludere “indipendenti” da r ≈ 0', 'Interpretare la correlazione come pendenza: la pendenza è ρσ<sub>Y</sub>/σ<sub>X</sub>', 'Pensare che marginali normali implichino una congiunta normale', 'Dimenticare che la regressione di X su Y non è l’inversa di quella di Y su X'],
    avanzato: '<h3>Regressione verso la media</h3><p>Con varianze uguali, E(Y | X = x) = ρx con |ρ| &lt; 1: valori estremi di X sono accompagnati, in media, da valori di Y meno estremi. È il fenomeno osservato da Galton sulle altezze di padri e figli, ed è una conseguenza della correlazione imperfetta, non di un meccanismo causale.</p><h3>Copule</h3><p>Per il teorema di Sklar ogni legge congiunta continua si scrive come C(F<sub>X</sub>(x), F<sub>Y</sub>(y)): le marginali e la struttura di dipendenza (la copula C) si separano. La normale bivariata ha copula gaussiana; esistono congiunte con marginali normali ma copula diversa, e quindi non normali.</p><h3>Misure di dipendenza oltre la correlazione</h3><p>Il ρ di Spearman (correlazione dei ranghi) e il τ di Kendall dipendono solo dalla copula e sono invarianti per trasformazioni monotone; la correlazione di distanza di Székely è nulla se e solo se c’è indipendenza.</p>',
    esercizi: [['Mostra che Cov(X, X²) = 0 se X ~ N(0, 1). Le due variabili sono indipendenti?', 'Cov = E X³ − E X · E X² = 0 per simmetria. Non sono indipendenti: X² è funzione di X.'], ['Per la normale bivariata standard con ρ = 0,8, quanto vale Var(Y | X = 2)?', '1 − ρ² = 0,36: non dipende da x.'], ['Perché la striscia con h molto piccolo dà stime instabili?', 'Contiene pochi punti: la varianza dello stimatore è dell’ordine di 1/(n h).']],
    riferimenti: ['Casella G., Berger R. L. (2002). Statistical Inference, 2ª ed., cap. 4.', 'Nelsen R. B. (2006). An Introduction to Copulas, 2ª ed. Springer.', 'Székely G. J., Rizzo M. L., Bakirov N. K. (2007). Measuring and testing dependence by correlation of distances. Annals of Statistics 35, 2769–2794.']
  },
  simulazione: {
    obiettivi: ['Generare qualunque legge a partire da uniformi con il metodo di inversione', 'Comprendere l’inversa generalizzata per le leggi discrete', 'Stimare un integrale con il metodo Monte Carlo', 'Confrontare stimatori Monte Carlo attraverso la loro varianza'],
    valutiamo: [['Correttezza dell’inversione', 'l’istogramma dei valori generati contro la legge teorica'], ['Percorso u → x', 'la linea arancione: dall’asse verticale alla curva e giù fino all’asse x'], ['Precisione Monte Carlo', 'le due stime dell’integrale contro il valore esatto e le bande ±1,96σ/√n'], ['Efficienza', 'il rapporto delle varianze tra hit-or-miss e media di f(U)']],
    tabella: 'Nell’inversione, la tabella confronta momenti teorici e simulati: coincidono a meno di errore Monte Carlo. Nell’integrazione, la colonna “errore standard stimato” è l’incertezza della stima dopo n coppie; la varianza teorica per coppia spiega perché un metodo converge più in fretta.',
    esempio: '<p><strong>Esempio svolto.</strong> Per I = ∫₀¹ x² dx = 1/3: Var(U²) = E U⁴ − (E U²)² = 1/5 − 1/9 = 4/45 ≈ 0,089, mentre l’hit-or-miss ha varianza I(1 − I) = 2/9 ≈ 0,222. Il rapporto 2,5 significa che l’hit-or-miss richiede 2,5 volte più coppie per la stessa precisione.</p>',
    errori: ['Usare l’inversa ordinaria per una legge discreta: serve l’estremo inferiore {x : F(x) ≥ u}', 'Credere che il seed renda i numeri “meno casuali”: rende l’esperimento riproducibile', 'Leggere una singola simulazione fortunata come prova di superiorità di un metodo', 'Dimenticare che l’errore Monte Carlo decresce solo come 1/√n'],
    avanzato: '<h3>Accettazione-rifiuto</h3><p>Se f ≤ c g e si sa generare da g, si genera Y ~ g e U ~ U(0, 1) e si accetta Y se U ≤ f(Y)/(c g(Y)). L’hit-or-miss è il caso g uniforme: la probabilità di accettazione 1/c è l’area sotto f.</p><h3>Riduzione della varianza</h3><p>Variabili antitetiche (usare U e 1 − U), variabili di controllo (sottrarre c(h(U) − E h(U)) con E h noto), campionamento per importanza (generare da g e pesare con f/g), stratificazione. Il condizionamento, visto qui, è il caso più semplice: Var E[Z | U] ≤ Var Z.</p><h3>Generatori pseudocasuali</h3><p>Il Mersenne-Twister di R ha periodo 2<sup>19937</sup> − 1 e buona equidistribuzione fino a 623 dimensioni, ma non è adatto alla crittografia. StatAtlas lo replica esattamente, compreso lo “scrambling” iniziale di set.seed.</p>',
    esercizi: [['Scrivi la funzione quantile della Weibull(k, λ) e verifica che coincide con qweibull.', 'F(x) = 1 − exp{−(x/λ)<sup>k</sup>} ⇒ F⁻¹(u) = λ(−log(1 − u))<sup>1/k</sup>.'], ['Con le variabili antitetiche, stima ∫₀¹ eˣ dx usando (f(U) + f(1 − U))/2. Perché la varianza diminuisce?', 'f è monotona, quindi f(U) e f(1 − U) sono negativamente correlate e la varianza della media è minore di quella con due U indipendenti.'], ['Quante coppie servono perché l’errore standard dell’hit-or-miss per I = 1/3 sia 0,001?', 'σ²/n = 0,222/n = 10⁻⁶ ⇒ n ≈ 222 000.']],
    riferimenti: ['Devroye L. (1986). Non-Uniform Random Variate Generation. Springer (liberamente disponibile online).', 'Robert C. P., Casella G. (2004). Monte Carlo Statistical Methods, 2ª ed. Springer.', 'Matsumoto M., Nishimura T. (1998). Mersenne Twister. ACM Transactions on Modeling and Computer Simulation 8, 3–30.']
  },
  'lgn-tcl': {
    obiettivi: ['Distinguere convergenza della media (LGN) e forma della sua distribuzione (TCL)', 'Distinguere ciò che è esatto per ogni n da ciò che vale solo al limite', 'Quantificare la velocità di approssimazione con asimmetria e Berry–Esseen', 'Riconoscere i casi in cui i teoremi non valgono'],
    valutiamo: [['Convergenza delle traiettorie', 'quanto le quattro medie si avvicinano a μ e restano nella banda'], ['Forma della distribuzione delle medie', 'l’istogramma delle medie standardizzate contro la N(0, 1)'], ['Velocità', 'asimmetria osservata contro γ/√n e distanza da Φ contro il limite di Berry–Esseen'], ['Fallimento', 'il comportamento della Cauchy']],
    tabella: 'Media 0 e varianza 1 della media standardizzata sono esatte per ogni n; la coda P(|z| > 1,96) = 0,05 vale solo al limite. La distanza osservata include l’errore Monte Carlo (circa 1/√B), per questo con dati discreti può superare di poco il limite di Berry–Esseen.',
    esempio: '<p><strong>Esempio svolto.</strong> Dati Esponenziale(1): γ = 2. Con n = 10 l’asimmetria della media è 2/√10 ≈ 0,63, ancora ben visibile; con n = 100 scende a 0,2. Per avere asimmetria 0,1 servono n = 400 osservazioni.</p>',
    errori: ['Credere che dopo una serie di valori alti “debbano” arrivare valori bassi (fallacia del giocatore)', 'Applicare il TCL ai singoli dati invece che alla media', 'Confondere n (numerosità del campione) con B (numero di campioni simulati)', 'Usare la normale per la media di dati con varianza infinita'],
    avanzato: '<h3>Legge forte e legge del logaritmo iterato</h3><p>Le traiettorie convergono quasi certamente (Kolmogorov), e la legge del logaritmo iterato descrive l’ampiezza esatta delle oscillazioni: lim sup (x̄ₙ − μ)/(σ√(2 log log n / n)) = 1. Le traiettorie escono dalla banda ±1,96σ/√n infinite volte, ma sempre più raramente in proporzione.</p><h3>Teorema di Lindeberg–Feller</h3><p>Per somme di variabili indipendenti non identicamente distribuite la normalità limite vale se nessun termine domina (condizione di Lindeberg). È il fondamento della normalità asintotica degli stimatori in regressione.</p><h3>Metodo delta</h3><p>Se √n(x̄ₙ − μ) → N(0, σ²) e g è derivabile con g′(μ) ≠ 0, allora √n(g(x̄ₙ) − g(μ)) → N(0, g′(μ)²σ²). Così si ottengono, per esempio, gli errori standard di log x̄ o di 1/x̄.</p>',
    esercizi: [['Con dati Bernoulli(0,35) e n = 30, la probabilità che x̄ superi 0,5 è piccola? Usa il TCL.', 'σ/√n = √(0,2275/30) ≈ 0,087; z = (0,5 − 0,35)/0,087 ≈ 1,72 ⇒ circa 0,043 (con correzione di continuità ≈ 0,06).'], ['Perché per la Cauchy la media di n osservazioni ha la stessa legge di una sola?', 'Funzione caratteristica e<sup>−|t|</sup>: φ(t/n)ⁿ = e<sup>−|t|</sup>. La Cauchy è stabile con indice 1.'], ['Calcola il limite di Berry–Esseen per l’Uniforme con n = 10.', '0,4748 · 1,299/√10 ≈ 0,195: una garanzia molto prudente rispetto alla distanza effettiva, molto più piccola.']],
    riferimenti: ['Billingsley P. (1995). Probability and Measure, 3ª ed. Wiley, §§ 6, 27.', 'Shevtsova I. (2011). On the absolute constants in the Berry–Esseen type inequalities. arXiv:1111.6554.', 'Wasserman L. (2004). All of Statistics. Springer, cap. 5.']
  },
  adattamento: {
    obiettivi: ['Valutare graficamente l’adattamento con istogramma e QQ plot', 'Costruire correttamente il test X²: classi, attese minime, gradi di libertà', 'Capire l’effetto della stima dei parametri sulla distribuzione del test', 'Usare il bootstrap parametrico per un p-value affidabile'],
    valutiamo: [['Accordo globale', 'il p-value del test X² (asintotico e Monte Carlo)'], ['Dove il modello sbaglia', 'gli scostamenti del QQ plot dalla retta, soprattutto nelle code'], ['Potenza del test', 'come cambia la decisione aumentando N con un modello sbagliato'], ['Errore di primo tipo', 'quanto spesso si rifiuta quando il modello è quello vero']],
    tabella: 'X² misura la distanza tra frequenze osservate e attese; i gradi di libertà sono classi − 1 − parametri stimati. Il p-value asintotico usa la χ²; quello Monte Carlo ricostruisce la distribuzione di X² sotto il modello stimato ed è più affidabile. La distanza di Kolmogorov è indicativa: con parametri stimati non si usano le tabelle classiche.',
    esempio: '<p><strong>Esempio svolto.</strong> 200 dati da una Gamma(2, 1) confrontati con una Normale stimata: X² ≈ 62 con 17 gradi di libertà. Poiché E χ²₁₇ = 17 e Var = 34, un valore di 62 è a più di 7 deviazioni standard: p ≈ 5·10⁻⁷. Il QQ plot mostra il motivo: la coda destra dei dati è più lunga di quella normale.</p>',
    errori: ['Interpretare un p-value grande come prova che il modello è giusto', 'Usare classi con frequenze attese molto piccole', 'Dimenticare di togliere i gradi di libertà per i parametri stimati', 'Usare il test di Kolmogorov–Smirnov con parametri stimati e tabelle classiche'],
    avanzato: '<h3>Test basati sulla funzione di ripartizione empirica</h3><p>Oltre a Kolmogorov (sup|F̂ − F|), Cramér–von Mises (∫(F̂ − F)² dF) e Anderson–Darling (che pesa di più le code con 1/[F(1 − F)]) sono in genere più potenti. Con parametri stimati la loro distribuzione dipende dalla famiglia: tavole specifiche o bootstrap parametrico.</p><h3>Test di normalità</h3><p>Shapiro–Wilk confronta i quantili ordinati con i quantili normali attesi tramite una combinazione lineare ottimale; è tra i test più potenti contro molte alternative. In R: <code>shapiro.test()</code>.</p><h3>Selezione del numero di classi</h3><p>Per il X² con classi equiprobabili, Mann e Wald suggerirono k ≈ 4(2n²/z²)<sup>1/5</sup>; nella pratica si bilanciano potenza e validità dell’approssimazione (attese ≥ 5).</p>',
    esercizi: [['Con k = 10 classi e 2 parametri stimati, quanti gradi di libertà ha il X²? E se i parametri fossero noti?', '10 − 1 − 2 = 7; con parametri noti 9.'], ['Una curva a forma di S nel QQ plot normale che cosa indica?', 'Code diverse dalla normale: S con estremi che si allontanano verso l’esterno indica code più pesanti.'], ['Perché con N = 2000 si rifiuta quasi sempre anche un modello “quasi giusto”?', 'La potenza cresce con N: anche piccole discrepanze diventano statisticamente significative, senza essere necessariamente rilevanti.']],
    riferimenti: ['D’Agostino R. B., Stephens M. A. (1986). Goodness-of-Fit Techniques. Marcel Dekker.', 'Chernoff H., Lehmann E. L. (1954). The use of maximum likelihood estimates in χ² tests for goodness of fit. Annals of Mathematical Statistics 25, 579–586.', 'Lilliefors H. W. (1967). On the Kolmogorov–Smirnov test for normality with mean and variance unknown. JASA 62, 399–402.']
  },
  stimatori: {
    obiettivi: ['Confrontare stimatori diversi sugli stessi campioni', 'Usare distorsione, varianza, errore quadratico medio e robustezza come criteri', 'Collegare l’efficienza alla forma delle code della popolazione', 'Distinguere esattezza, asintotica e Monte Carlo nei risultati'],
    valutiamo: [['Centro', 'se le stime si distribuiscono attorno a θ'], ['Precisione', 'la larghezza delle distribuzioni campionarie (dev. std e scarto interquartile)'], ['Efficienza relativa', 'il rapporto delle varianze contro il valore asintotico'], ['Robustezza', 'il comportamento con code pesanti (Laplace, Cauchy)']],
    tabella: 'Ogni riga è uno stimatore. “Centro” è la mediana delle stime (esiste sempre); dev. std ed errore quadratico medio sono confrontati con la teoria, quando esiste. Per la media di dati Cauchy la teoria non ha varianza: il † segnala che il numero simulato non converge.',
    esempio: '<p><strong>Esempio svolto.</strong> Dati normali, n = 20: Var(x̄) = 1/20 = 0,05, Var(mediana) ≈ π/40 ≈ 0,0785. L’efficienza della mediana è 0,64: con la mediana servono circa 31 osservazioni per ottenere la precisione della media con 20.</p>',
    errori: ['Scegliere uno stimatore guardando una sola simulazione', 'Credere che lo stimatore “migliore” lo sia per ogni legge dei dati', 'Usare la varianza per confrontare stimatori con code pesanti, invece di scarti interquartili', 'Chiamare la mediana MLE della Cauchy'],
    avanzato: '<h3>Media troncata e M-stimatori</h3><p>La media troncata al 10% scarta il 10% delle osservazioni per lato: ha efficienza 0,94 sotto normalità e resta robusta. Gli M-stimatori (M-estimators) di Huber minimizzano Σρ(xᵢ − θ) con ρ quadratica al centro e lineare nelle code: un compromesso continuo tra media e mediana.</p><h3>Funzione di influenza</h3><p>IF(x) misura l’effetto di una contaminazione infinitesima in x: per la media è x − θ (illimitata), per la mediana sign(x − θ)/(2f(θ)) (limitata). La varianza asintotica è E IF², da cui si ricavano tutte le efficienze del laboratorio.</p><h3>Efficienza relativa asintotica</h3><p>Per la mediana contro la media in una famiglia di posizione, ARE = 4f(θ)²σ². Per ogni legge simmetrica unimodale ARE ≥ 1/3 (e il minimo si raggiunge con l’uniforme); per code pesanti può essere arbitrariamente grande.</p>',
    esercizi: [['Calcola l’efficienza della mediana rispetto alla media per la Laplace con b = 1.', 'Var(x̄) = 2/n, Var(mediana) ≈ 1/(4n f(0)²) = 1/n ⇒ ARE = 2.'], ['Perché la media di dati Cauchy non migliora aumentando n?', 'x̄ ~ Cauchy(θ, 1) per ogni n: la sua dispersione non dipende da n.'], ['Proponi uno stimatore robusto ed efficiente per dati quasi normali con pochi valori anomali.', 'Media troncata al 10–20% o M-stimatore di Huber: perdono pochissimo sotto normalità e limitano l’influenza dei valori anomali.']],
    riferimenti: ['Huber P. J., Ronchetti E. M. (2009). Robust Statistics, 2ª ed. Wiley.', 'Lehmann E. L., Casella G. (1998). Theory of Point Estimation, 2ª ed. Springer.', 'Hampel F. R. et al. (1986). Robust Statistics: The Approach Based on Influence Functions. Wiley.']
  },
  fisher: {
    obiettivi: ['Leggere la log-verosimiglianza di un campione come funzione del parametro', 'Interpretare score e informazione osservata e attesa', 'Verificare le identità di Bartlett e il limite di Cramér–Rao', 'Confrontare intervalli di Wald e del rapporto di verosimiglianza; riconoscere i modelli non regolari'],
    valutiamo: [['Curvatura', 'quanto è appuntita la log-verosimiglianza: più curvatura, più informazione'], ['Bontà dell’approssimazione quadratica', 'la curva tratteggiata contro quella vera'], ['Identità di Bartlett', 'media dello score ≈ 0, varianza dello score ≈ media dell’informazione osservata ≈ n I(θ)'], ['Efficienza', 'la varianza di θ̂ contro il limite 1/(n I(θ))']],
    tabella: 'Le prime tre righe verificano le identità esatte che legano score e informazione. Le successive confrontano media e varianza di θ̂ con i valori esatti (quando noti) e con il limite di Cramér–Rao; le ultime due misurano la copertura reale di due intervalli al 95% costruiti dalla verosimiglianza.',
    esempio: '<p><strong>Esempio svolto.</strong> Esponenziale(λ = 1), n = 20: ℓ(λ) = 20 log λ − λΣxᵢ, λ̂ = 1/x̄, J(λ) = 20/λ², I(λ) = 1/λ². Cramér–Rao: 1/20 = 0,05. Ma λ̂ è distorto (E λ̂ = 20/19) e la sua varianza esatta è 400/(19²·18) ≈ 0,0616: il limite vale per stimatori non distorti, e λ̂ lo raggiunge solo asintoticamente.</p>',
    errori: ['Interpretare la verosimiglianza come la probabilità del parametro', 'Applicare Cramér–Rao a stimatori distorti o a modelli non regolari', 'Usare l’intervallo di Wald quando la verosimiglianza è molto asimmetrica', 'Dimenticare che I(θ) è per osservazione: l’informazione del campione è n I(θ)'],
    avanzato: '<h3>Riparametrizzazione</h3><p>Se ψ = g(θ), allora I<sub>ψ</sub>(ψ) = I<sub>θ</sub>(θ)/g′(θ)². L’intervallo di Wald dipende dalla parametrizzazione, quello del rapporto di verosimiglianza no. Esiste una parametrizzazione che rende l’informazione costante (stabilizzazione della varianza, es. √λ per la Poisson).</p><h3>Parametri di disturbo</h3><p>Con più parametri l’informazione diventa una matrice; la varianza asintotica di θ̂₁ è [I⁻¹]₁₁ ≥ 1/I₁₁: non conoscere gli altri parametri costa informazione. La verosimiglianza profilo ℓ<sub>p</sub>(θ₁) = max<sub>θ₂</sub> ℓ(θ₁, θ₂) estende il rapporto di verosimiglianza.</p><h3>Test score, Wald e rapporto di verosimiglianza</h3><p>Sono asintoticamente equivalenti sotto H₀ (tutti χ²), ma diversi per n finito: lo score usa la curvatura in θ₀, Wald in θ̂, il rapporto di verosimiglianza l’intera curva tra i due.</p>',
    esercizi: [['Calcola l’informazione di Fisher per la Bernoulli(p) e il limite di Cramér–Rao per n = 50, p = 0,3.', 'I(p) = 1/[p(1 − p)] ⇒ CR = p(1 − p)/n = 0,21/50 = 0,0042.'], ['Perché il modello Uniforme (0, θ) non è regolare?', 'Il supporto dipende da θ: non si può derivare sotto il segno di integrale e la log-verosimiglianza ha il massimo su un bordo.'], ['Con ℓ(θ̂) − ℓ(θ₀) = 2,5, il test del rapporto di verosimiglianza rifiuta H₀: θ = θ₀ al 5%?', '2 · 2,5 = 5 &gt; 3,84 = χ²₁,₀.₉₅: sì.']],
    riferimenti: ['Azzalini A. (1996). Statistical Inference Based on the Likelihood. Chapman & Hall.', 'Pawitan Y. (2001). In All Likelihood. Oxford University Press.', 'Casella G., Berger R. L. (2002). Statistical Inference, 2ª ed., capp. 7 e 10.']
  },
  intervalli: {
    obiettivi: ['Interpretare correttamente il livello di confidenza', 'Distinguere metodi pivotali, asintotici ed esatti per dati discreti', 'Calcolare la copertura reale di un metodo', 'Valutare il compromesso tra copertura e ampiezza'],
    valutiamo: [['Copertura', 'la frazione di intervalli che contengono il vero valore, contro il livello nominale'], ['Copertura esatta', 'la vera probabilità di copertura del metodo, calcolata (linea verde)'], ['Ampiezza', 'quanto sono larghi gli intervalli in media'], ['Casi critici', 'p vicino a 0 o 1, n piccolo, intervalli degeneri']],
    tabella: 'Nominale è il livello dichiarato; Esatta è la vera probabilità di copertura del metodo con questi parametri (per Bernoulli e Poisson calcolata sommando su tutti i valori possibili della statistica sufficiente); Simulazione è la frequenza osservata, con il suo margine Monte Carlo.',
    esempio: '<p><strong>Esempio svolto.</strong> Wald per una proporzione con p = 0,1 e n = 20: P(p̂ = 0) = 0,9²⁰ ≈ 0,12, e in quel caso l’intervallo è il solo punto 0, che non copre mai. Già questo sottrae il 12% di copertura: la copertura esatta è 87,6%, non 95%.</p>',
    errori: ['Dire “θ sta nell’intervallo con probabilità 95%” dopo averlo calcolato', 'Usare Wald per proporzioni con np(1 − p) piccolo', 'Pensare che un intervallo esatto abbia copertura esattamente nominale con dati discreti', 'Confrontare metodi solo per la copertura, ignorando l’ampiezza'],
    avanzato: '<h3>Clopper–Pearson</h3><p>Per la binomiale, l’analogo di Garwood inverte due test unilaterali esatti: [B(α/2; s, n − s + 1), B(1 − α/2; s + 1, n − s)] con B quantili Beta. Copertura ≥ nominale per ogni p, spesso molto conservativa: Agresti e Coull raccomandano Wilson o il loro intervallo “aggiustato” (aggiungere 2 successi e 2 insuccessi).</p><h3>Intervalli bootstrap</h3><p>Quando non c’è un pivot noto si ricampiona: percentile, BCa, bootstrap-t. Hanno copertura asintoticamente corretta, con errori di ordine 1/√n (percentile) o 1/n (BCa, bootstrap-t).</p><h3>Interpretazione bayesiana</h3><p>Un intervallo di credibilità soddisfa P(θ ∈ C | dati) = 0,95: è l’affermazione che spesso si vorrebbe fare, ma richiede una distribuzione a priori. Per molte situazioni regolari i due approcci danno intervalli numericamente simili.</p>',
    esercizi: [['Calcola l’intervallo Z al 95% con x̄ = 10,4, σ = 2, n = 25.', '10,4 ± 1,96 · 2/5 = [9,616; 11,184].'], ['Con S = 0 eventi in n = 10 osservazioni Poisson, quanto vale l’estremo superiore di Garwood al 95%?', 'χ²₂;₀.₉₇₅/(2·10) = 7,378/20 ≈ 0,369.'], ['Perché l’intervallo t è in media più largo dello Z?', 't<sub>n−1</sub> &gt; z e la stima s introduce variabilità aggiuntiva; per n → ∞ la differenza svanisce.']],
    riferimenti: ['Brown L. D., Cai T. T., DasGupta A. (2001). Interval estimation for a binomial proportion. Statistical Science 16, 101–133.', 'Agresti A., Coull B. A. (1998). Approximate is better than “exact”. The American Statistician 52, 119–126.', 'Garwood F. (1936). Fiducial limits for the Poisson distribution. Biometrika 28, 437–442.']
  },
  test: {
    obiettivi: ['Distinguere errore di primo e di secondo tipo', 'Calcolare e interpretare la potenza', 'Dimensionare un campione per una potenza desiderata', 'Interpretare correttamente il p-value'],
    valutiamo: [['Errore di primo tipo', 'frequenza dei rifiuti quando H₀ è vera, contro α'], ['Potenza', 'frequenza dei rifiuti quando H₁ è vera, contro il valore teorico'], ['Ruolo di n e δ', 'come la curva di potenza si sposta con n e con l’effetto'], ['Bilaterale contro unilaterale', 'come cambia la potenza dividendo α tra due code']],
    tabella: 'La prima riga verifica che il test rispetti il livello scelto; la seconda che la potenza simulata coincida con la formula; la terza è il complemento della potenza (l’effetto c’è ma non viene visto). L’errore Monte Carlo è indicato accanto ai valori simulati.',
    esempio: '<p><strong>Esempio svolto.</strong> δ = 0,5, α = 0,05 bilaterale, n = 20: spostamento atteso δ√n = 2,236; potenza ≈ Φ(2,236 − 1,96) = Φ(0,276) ≈ 0,609. Per potenza 80% servono n ≈ ((1,96 + 0,842)/0,5)² ≈ 32 osservazioni.</p>',
    errori: ['Interpretare il p-value come probabilità che H₀ sia vera', 'Concludere “nessun effetto” da un test non significativo con bassa potenza', 'Scegliere il test unilaterale dopo aver visto i dati', 'Confondere significatività statistica e rilevanza pratica'],
    avanzato: '<h3>Test multipli</h3><p>Con m test indipendenti al 5%, la probabilità di almeno un falso positivo è 1 − 0,95<sup>m</sup> (64% con m = 20). Bonferroni controlla questo rischio usando α/m; Benjamini–Hochberg controlla il tasso atteso di false scoperte ed è molto più potente.</p><h3>Potenza post hoc</h3><p>Calcolare la potenza usando l’effetto stimato dai dati stessi non aggiunge informazione: è una funzione monotona del p-value. La potenza va calcolata prima, per un effetto ritenuto rilevante.</p><h3>Errore di tipo S e M</h3><p>Con bassa potenza, i risultati significativi sovrastimano sistematicamente l’effetto (errore di tipo M, magnitudo) e possono perfino avere il segno sbagliato (tipo S): un motivo in più per dimensionare bene gli studi (Gelman e Carlin, 2014).</p>',
    esercizi: [['Qual è la potenza del test Z unilaterale con δ = 0,3, n = 50, α = 0,05?', 'Φ(0,3√50 − 1,645) = Φ(2,121 − 1,645) = Φ(0,476) ≈ 0,68.'], ['Quante osservazioni servono per potenza 90% con δ = 0,4, α = 0,05 bilaterale?', '((1,96 + 1,282)/0,4)² ≈ 65,7 ⇒ 66.'], ['Perché sotto H₀ il p-value è uniforme?', 'Se T ha ripartizione continua F sotto H₀, p = 1 − F(T) e F(T) ~ U(0, 1).']],
    riferimenti: ['Lehmann E. L., Romano J. P. (2005). Testing Statistical Hypotheses, 3ª ed. Springer.', 'Wasserstein R. L., Lazar N. A. (2016). The ASA statement on p-values. The American Statistician 70, 129–133.', 'Gelman A., Carlin J. (2014). Beyond power calculations. Perspectives on Psychological Science 9, 641–651.']
  },
  regressione: {
    obiettivi: ['Stimare e interpretare una retta di regressione', 'Distinguere intervallo per la media e intervallo di previsione', 'Riconoscere punti ad alto leverage e osservazioni influenti', 'Verificare quando le coperture nominali sono affidabili'],
    valutiamo: [['Sensibilità della retta', 'come si sposta trascinando un punto, al centro o ai bordi'], ['Bande', 'la banda per E(Y | x) contro l’intervallo di previsione per una nuova Y'], ['Influenza', 'leverage, residui standardizzati e distanza di Cook'], ['Validità degli intervalli', 'le coperture simulate con errori normali, a code pesanti e asimmetrici']],
    tabella: 'Le prime due righe verificano che la pendenza stimata sia non distorta con deviazione standard σ/√Sxx (vero per qualunque legge degli errori con varianza σ²). Le ultime due misurano la copertura dei due intervalli in x₀: esatte con errori normali, solo approssimate altrimenti.',
    esempio: '<p><strong>Esempio svolto.</strong> Con n = 12 punti equispaziati in [0, 10], Sxx ≈ 99,3: se σ = 1,5 la deviazione standard di β̂₁ è 1,5/√99,3 ≈ 0,151. Raddoppiare l’ampiezza dell’intervallo delle x quadruplica Sxx e dimezza l’incertezza sulla pendenza.</p>',
    errori: ['Usare l’intervallo per la media quando si vuole prevedere un singolo valore', 'Eliminare i punti influenti senza indagarne il motivo', 'Estrapolare la retta lontano dall’intervallo delle x osservate', 'Leggere R² alto come prova che il modello lineare sia corretto'],
    avanzato: '<h3>Diagnostica dei residui</h3><p>Grafico residui contro valori stimati (forme a imbuto indicano eteroschedasticità, curve indicano non linearità), QQ plot dei residui (normalità), residui contro tempo (correlazione). In R: <code>plot(lm)</code> produce i quattro grafici classici.</p><h3>Errori standard robusti</h3><p>Con eteroschedasticità gli stimatori OLS restano non distorti ma gli errori standard classici sono sbagliati; gli errori “sandwich” di White, (XᵀX)⁻¹XᵀΩ̂X(XᵀX)⁻¹, sono consistenti (pacchetto <code>sandwich</code>).</p><h3>Leverage e disegno sperimentale</h3><p>Var(β̂₁) = σ²/Sxx: per stimare una pendenza conviene concentrare le x agli estremi, ma così non si può più verificare la linearità. Il disegno ottimo dipende dallo scopo.</p>',
    esercizi: [['Mostra che la retta dei minimi quadrati passa per (x̄, ȳ).', 'β̂₀ = ȳ − β̂₁x̄ ⇒ ŷ(x̄) = ȳ.'], ['Perché i residui di punti ad alto leverage tendono a essere piccoli?', 'Var(eᵢ) = σ²(1 − hᵢ): con hᵢ vicino a 1 la retta passa quasi per il punto.'], ['Con s = 1,2, n = 20, x₀ = x̄, quanto è largo l’intervallo di previsione al 95%?', '2 · t₁₈ · 1,2 · √(1 + 1/20) ≈ 2 · 2,101 · 1,23 ≈ 5,17.']],
    riferimenti: ['Weisberg S. (2014). Applied Linear Regression, 4ª ed. Wiley.', 'Cook R. D. (1977). Detection of influential observation in linear regression. Technometrics 19, 15–18.', 'Fox J. (2016). Applied Regression Analysis and Generalized Linear Models, 3ª ed. Sage.']
  },
  'regressione-lp': {
    obiettivi: ['Confrontare criteri di stima diversi sugli stessi dati', 'Collegare ciascun criterio alla legge degli errori per cui è ottimo', 'Valutare robustezza ed efficienza con code pesanti e contaminazione', 'Comprendere l’algoritmo dei minimi quadrati ponderati iterativi (IRLS)'],
    valutiamo: [['Precisione', 'la larghezza delle distribuzioni delle pendenze per L2, L1 e Lp'], ['Robustezza', 'quanto le rette resistono a valori anomali nella y'], ['Efficienza relativa', 'il rapporto delle varianze asintotiche L2/L1'], ['Ruolo di p', 'come cambia la precisione spostando p tra 1 e 3']],
    tabella: 'Per ogni criterio: media, dev. std, scarto interquartile ed errore quadratico medio delle pendenze simulate. Sotto la dev. std simulata c’è quella asintotica (da Eψ²/(Eψ′)²): per gli errori t₂ quella dei minimi quadrati non esiste.',
    esempio: '<p><strong>Esempio svolto.</strong> Errori normali contaminati (10% con scala 10): la varianza è 0,9 + 0,1·100 = 10,9, mentre la densità in 0 resta ≈ 0,363. Efficienza L1/L2 = 4·0,363²·10,9 ≈ 5,7: i minimi quadrati richiedono circa sei volte più dati.</p>',
    errori: ['Pensare che L1 sia robusto anche ai valori anomali nella x', 'Scegliere il criterio dopo aver guardato quale dà il risultato “migliore”', 'Fidarsi degli errori standard di lm() con errori a varianza infinita', 'Considerare l’IRLS esatto per p = 1: converge lentamente; esistono algoritmi esatti'],
    avanzato: '<h3>Regressione quantile</h3><p>L1 stima la mediana condizionata. Pesando diversamente residui positivi e negativi (perdita ρ<sub>τ</sub>(r) = r(τ − 1{r &lt; 0})) si stima il quantile τ condizionato: la regressione quantile di Koenker e Bassett descrive l’intera distribuzione condizionata.</p><h3>Stimatori ad alto punto di rottura</h3><p>LMS e LTS minimizzano la mediana dei quadrati o la somma dei più piccoli: resistono fino al 50% di contaminazione, anche nella x. Gli MM-stimatori combinano alto punto di rottura ed efficienza elevata (<code>robustbase::lmrob</code>).</p><h3>Normale generalizzata</h3><p>f(e) ∝ exp{−|e/α|<sup>p</sup>}: p = 2 normale, p = 1 Laplace, p → ∞ uniforme. Lp è la massima verosimiglianza per questa famiglia; stimare anche p dai dati è una forma di adattamento del criterio.</p>',
    esercizi: [['Per quale legge degli errori L1 è lo stimatore di massima verosimiglianza?', 'Laplace: log f = −|e|/b + costante.'], ['Calcola l’efficienza L1/L2 per errori normali.', '4f(0)²σ² = 4 · (1/2π) = 2/π ≈ 0,64.'], ['Perché i pesi IRLS sono |r|<sup>p−2</sup>?', 'Il gradiente di Σ|rᵢ|<sup>p</sup> è −pΣ|rᵢ|<sup>p−2</sup>rᵢxᵢ: si annulla dove si annulla quello dei minimi quadrati ponderati con tali pesi.']],
    riferimenti: ['Koenker R. (2005). Quantile Regression. Cambridge University Press.', 'Huber P. J., Ronchetti E. M. (2009). Robust Statistics, 2ª ed. Wiley.', 'Rousseeuw P. J., Leroy A. M. (1987). Robust Regression and Outlier Detection. Wiley.']
  },
  glm: {
    obiettivi: ['Specificare un GLM: legge, predittore lineare, legame', 'Interpretare i coefficienti come odds ratio o rapporti di medie', 'Comprendere la stima con IRLS e le sue proprietà asintotiche', 'Riconoscere distorsione per n piccolo e separazione'],
    valutiamo: [['Adattamento', 'la curva stimata contro quella vera sul campione corrente'], ['Distribuzione delle stime', 'l’istogramma di β̂₁ contro la normale asintotica'], ['Distorsione', 'il triangolo arancione (media delle stime) contro la linea tratteggiata (vero β₁)'], ['Separazione', 'la frazione di campioni senza stima finita']],
    tabella: 'Tutte le righe teoriche sono asintotiche: per n grande β̂₁ è normale con varianza (XᵀWX)⁻¹ e la copertura di Wald è 0,95. Con n piccolo le differenze tra teoria e simulazione misurano quanto quell’approssimazione è lontana dalla realtà.',
    esempio: '<p><strong>Esempio svolto.</strong> Logistica con β₁ = 1,2: e<sup>1,2</sup> ≈ 3,32, cioè ogni unità di x moltiplica gli odds di successo per 3,3. Con n = 10 circa il 18% dei campioni è separabile; tra gli altri la stima media è ≈ 1,41, distorta del 17% verso l’esterno.</p>',
    errori: ['Interpretare β₁ della logistica come variazione di probabilità', 'Ignorare l’avviso di separazione di glm()', 'Usare la devianza come test di adattamento con dati binari individuali', 'Dimenticare la sovradispersione nei conteggi'],
    avanzato: '<h3>Correzione di Firth</h3><p>Massimizzare ℓ(β) + ½ log det I(β) (prior di Jeffreys) elimina la distorsione di primo ordine e garantisce stime finite anche con separazione (pacchetto <code>logistf</code> o <code>brglm2</code>).</p><h3>Sovradispersione</h3><p>Se Var(Y) &gt; μ nei conteggi, la Poisson sottostima gli errori standard. Rimedi: quasi-Poisson (Var = φμ, stesse stime, errori scalati per √φ̂) o binomiale negativa (Var = μ + μ²/k).</p><h3>Test nei GLM</h3><p>Wald (β̂/se), score e rapporto di verosimiglianza (differenza di devianze, <code>anova(fit, test = "LRT")</code>). In presenza di stime grandi il test di Wald può perdere potenza (effetto Hauck–Donner): preferire il rapporto di verosimiglianza.</p>',
    esercizi: [['In un modello logistico con β₁ = 0,7, di quanto cambiano gli odds per un aumento di 2 unità di x?', 'Fattore e<sup>1,4</sup> ≈ 4,06.'], ['Scrivi i pesi IRLS per la Poisson con legame logaritmico.', 'wᵢ = μᵢ = exp(ηᵢ); working response zᵢ = ηᵢ + (yᵢ − μᵢ)/μᵢ.'], ['Quando si verifica la separazione completa in una logistica con un solo predittore?', 'Quando esiste una soglia c tale che tutti gli y = 1 hanno x &gt; c e tutti gli y = 0 hanno x &lt; c (o viceversa).']],
    riferimenti: ['McCullagh P., Nelder J. A. (1989). Generalized Linear Models, 2ª ed. Chapman & Hall.', 'Agresti A. (2015). Foundations of Linear and Generalized Linear Models. Wiley.', 'Firth D. (1993). Bias reduction of maximum likelihood estimates. Biometrika 80, 27–38.']
  },
  arma: {
    obiettivi: ['Simulare processi AR, MA e ARMA', 'Leggere ACF e PACF per identificare il modello', 'Verificare stazionarietà e invertibilità tramite le radici', 'Comprendere la variabilità delle autocorrelazioni stimate'],
    valutiamo: [['Memoria', 'quanto decrescono le autocorrelazioni con il ritardo'], ['Identificazione', 'quale tra ACF e PACF si annulla dopo pochi ritardi'], ['Stabilità', 'la posizione delle radici rispetto al cerchio unitario'], ['Precisione delle stime', 'barre empiriche contro rombi teorici al crescere di T']],
    tabella: 'La colonna Teoria è calcolata esattamente dai coefficienti (pesi ψ e Durbin–Levinson). La colonna Serie simulata contiene le stime dalla serie generata finora: si avvicinano alla teoria al crescere di T se il processo è stazionario; altrimenti la teoria non è definita.',
    esempio: '<p><strong>Esempio svolto.</strong> AR(1) con φ = 0,8: γ(0) = 1/(1 − 0,64) ≈ 2,78, ρ(h) = 0,8<sup>h</sup> (ρ(5) ≈ 0,33), PACF nulla oltre il ritardo 1. Il tempo di dimezzamento della memoria è log 0,5/log 0,8 ≈ 3,1 periodi.</p>',
    errori: ['Stimare autocorrelazioni su una serie non stazionaria', 'Interpretare ogni barra fuori dalla banda come significativa (su 20 ritardi una esce per caso)', 'Dimenticare il burn-in nella simulazione', 'Scegliere un MA non invertibile: stessa ACF, modello non identificabile'],
    avanzato: '<h3>Previsione</h3><p>Per un AR(1) la previsione a h passi è φʰxₜ, con varianza dell’errore σ²(1 − φ<sup>2h</sup>)/(1 − φ²): la previsione converge alla media e l’incertezza alla varianza stazionaria. In R: <code>predict(arima(...), n.ahead = h)</code>.</p><h3>Radici unitarie e differenziazione</h3><p>Con una radice uguale a 1 (passeggiata aleatoria) la varianza cresce linearmente nel tempo; differenziando si ottiene un processo stazionario: modelli ARIMA(p, 1, q). Il test di Dickey–Fuller verifica la presenza di una radice unitaria.</p><h3>Stima e selezione</h3><p>I coefficienti si stimano per massima verosimiglianza (<code>arima</code>); l’ordine si sceglie con AIC/BIC e si verifica che i residui siano rumore bianco (test di Ljung–Box, <code>Box.test(type = "Ljung")</code>).</p>',
    esercizi: [['Il processo AR(2) con φ₁ = 0,5, φ₂ = 0,6 è stazionario?', 'φ₁ + φ₂ = 1,1 &gt; 1: no.'], ['Calcola ρ(1) per un MA(1) con θ = 0,7.', 'θ/(1 + θ²) = 0,7/1,49 ≈ 0,470.'], ['Perché un MA(1) con θ = 2 ha la stessa ACF di uno con θ = 0,5?', 'θ/(1 + θ²) è invariante per θ ↦ 1/θ: 2/5 = 0,5/1,25 = 0,4.']],
    riferimenti: ['Brockwell P. J., Davis R. A. (2016). Introduction to Time Series and Forecasting, 3ª ed. Springer.', 'Shumway R. H., Stoffer D. S. (2017). Time Series Analysis and Its Applications, 4ª ed. Springer (con esempi in R).', 'Box G. E. P., Jenkins G. M., Reinsel G. C., Ljung G. M. (2015). Time Series Analysis, 5ª ed. Wiley.']
  },
  quantilica: {
    obiettivi: ['Stimare quantili condizionati con la regressione quantilica', 'Interpretare la perdita asimmetrica ρτ', 'Riconoscere eteroschedasticità e asimmetria dal ventaglio delle rette', 'Confrontare robustezza e precisione con i minimi quadrati'],
    valutiamo: [['Forma della distribuzione condizionata', 'come si aprono le rette per τ = 0,1 … 0,9 al crescere di x'], ['Proprietà della soluzione', 'la quota di punti sotto ciascuna retta, che deve essere ≤ τ'], ['Robustezza', 'quanto si muove la retta mediana trascinando un punto anomalo, rispetto ai minimi quadrati'], ['Variabilità della stima', 'la distribuzione della pendenza quantilica nei campioni ripetuti']],
    tabella: 'Per ogni quantile: la pendenza vera del modello generatore, quella stimata sul campione corrente (calcolata esattamente) e la quota di punti sotto la retta. La quota non supera τ per costruzione: è una proprietà esatta della soluzione, non un risultato asintotico.',
    esempio: '<p><strong>Esempio svolto.</strong> Nel modello y = 2 + 0,6x + (0,3 + 0,25x)ε con ε normale, il quantile τ di y dato x è 2 + 0,6x + (0,3 + 0,25x)z<sub>τ</sub>. La pendenza vale 0,6 + 0,25z<sub>τ</sub>: 0,28 per τ = 0,1, 0,6 per la mediana, 0,92 per τ = 0,9. La differenza 0,64 tra le pendenze estreme misura quanto la dispersione cresce con x.</p>',
    errori: ['Interpretare β₁(τ) come effetto sul singolo individuo che sta al quantile τ', 'Pensare che la regressione quantilica richieda errori simmetrici o normali', 'Ignorare l’attraversamento delle rette stimate', 'Usare errori standard calcolati come per i minimi quadrati'],
    avanzato: '<h3>Equivarianza</h3><p>I quantili commutano con le trasformazioni monotone: Q<sub>τ</sub>(h(Y) | x) = h(Q<sub>τ</sub>(Y | x)). Si può stimare su log y e ritrasformare, cosa impossibile per la media (E log Y ≠ log E Y).</p><h3>Quantili estremi</h3><p>Per τ vicino a 0 o 1 le osservazioni informative sono poche e la stima è instabile: si ricorre alla teoria dei valori estremi.</p><h3>Inferenza</h3><p>In R: <code>summary(rq(...), se = "boot")</code> per il bootstrap, <code>anova(fit1, fit2)</code> per verificare se le pendenze differiscono tra quantili (test di uguaglianza delle pendenze, cioè di assenza di eteroschedasticità lineare).</p>',
    esercizi: [['Perché la retta della mediana passa per almeno due osservazioni?', 'Il problema è di programmazione lineare: l’ottimo è su un vertice, cioè un punto in cui p = 2 residui sono nulli.'], ['Con errori omoschedastici, come sono le rette quantiliche?', 'Parallele: differiscono solo per l’intercetta, pari a q<sub>τ</sub>(ε).'], ['Se trasformi y con il logaritmo, come cambia la retta della mediana?', 'Diventa la mediana condizionata di log y: per equivarianza è il logaritmo della mediana condizionata di y.']],
    riferimenti: ['Koenker R., Bassett G. (1978). Regression quantiles. Econometrica 46, 33–50.', 'Koenker R. (2005). Quantile Regression. Cambridge University Press.', 'Koenker R., Hallock K. F. (2001). Quantile regression. Journal of Economic Perspectives 15, 143–156.', 'Chernozhukov V., Fernández-Val I., Galichon A. (2010). Quantile and probability curves without crossing. Econometrica 78, 1093–1125.']
  },
  penalizzata: {
    obiettivi: ['Interpretare ridge, lasso ed elastic net come problemi con vincolo', 'Capire geometricamente perché il lasso seleziona le variabili', 'Leggere i percorsi di regolarizzazione', 'Quantificare il compromesso distorsione–varianza al variare di λ'],
    valutiamo: [['Geometria della soluzione', 'il punto in cui la curva di livello di RSS tocca la regione di vincolo'], ['Selezione', 'se la soluzione cade su un asse (un coefficiente esattamente nullo)'], ['Effetto della correlazione', 'come l’allungamento delle ellissi cambia le soluzioni'], ['Errore complessivo', 'distorsione², varianza ed errore quadratico medio contro i minimi quadrati']],
    tabella: 'Nella vista geometrica la tabella confronta le tre penalizzazioni con lo stesso vincolo t: coefficienti, quanti sono nulli e il λ equivalente. Nella vista dei percorsi riporta, per il λ selezionato, distorsione², varianza ed errore quadratico medio dei coefficienti stimati su M campioni con disegno fisso, a confronto con i minimi quadrati.',
    esempio: '<p><strong>Esempio svolto.</strong> Con predittori ortonormali e β̂<sup>OLS</sup> = (1,6; 0,7), il lasso con λ = 0,8 dà (0,8; 0): il secondo coefficiente è azzerato dalla soglia morbida. Il ridge con λ = 1 dà (0,8; 0,35): entrambi dimezzati, nessuno nullo.</p>',
    errori: ['Non standardizzare i predittori prima di penalizzare', 'Interpretare i coefficienti penalizzati come stime non distorte', 'Usare gli errori standard dei minimi quadrati dopo la selezione con il lasso', 'Scegliere λ guardando l’errore sui dati usati per la stima, invece che per validazione incrociata'],
    avanzato: '<h3>Interpretazione bayesiana</h3><p>Il ridge è la moda a posteriori con priori normali indipendenti sui coefficienti; il lasso con priori di Laplace. La forma della priori spiega la diversa geometria: la Laplace ha una cuspide in zero.</p><h3>Lasso adattivo</h3><p>Pesando la penalità con wⱼ = 1/|β̂ⱼ<sup>init</sup>|<sup>γ</sup> si ottiene uno stimatore con la proprietà di oracolo (selezione consistente e normalità asintotica) sotto condizioni opportune (Zou, 2006).</p><h3>Penalizzazioni non convesse</h3><p>SCAD e MCP riducono la distorsione sui coefficienti grandi mantenendo la sparsità (pacchetto <code>ncvreg</code>).</p>',
    esercizi: [['Con predittori ortonormali, scrivi la soluzione del ridge in funzione di β̂<sup>OLS</sup>.', 'β̂ⱼ = β̂ⱼ<sup>OLS</sup>/(1 + λ) nella parametrizzazione di glmnet: tutti ridotti dello stesso fattore.'], ['Perché il cerchio del ridge non produce soluzioni sugli assi?', 'Il suo bordo è liscio: il punto di tangenza con un’ellisse generica non coincide con un asse se non per configurazioni particolari.'], ['Con due predittori quasi identici, che cosa fa il lasso e che cosa l’elastic net?', 'Il lasso tende a sceglierne uno, in modo instabile tra campioni; l’elastic net assegna coefficienti simili a entrambi.']],
    riferimenti: ['Tibshirani R. (1996). Regression shrinkage and selection via the lasso. JRSS B 58, 267–288.', 'Hoerl A. E., Kennard R. W. (1970). Ridge regression: biased estimation for nonorthogonal problems. Technometrics 12, 55–67.', 'Zou H., Hastie T. (2005). Regularization and variable selection via the elastic net. JRSS B 67, 301–320.', 'Friedman J., Hastie T., Tibshirani R. (2010). Regularization paths for generalized linear models via coordinate descent. Journal of Statistical Software 33(1).', 'Hastie T., Tibshirani R., Wainwright M. (2015). Statistical Learning with Sparsity. CRC Press.']
  },
  spline: {
    obiettivi: ['Stimare una funzione senza imporne la forma', 'Mettere in relazione numero di basi, λ e banda con i gradi di libertà effettivi', 'Scomporre l’errore in distorsione² e varianza, esattamente', 'Scegliere la complessità con la validazione incrociata'],
    valutiamo: [['Aderenza', 'la curva stimata contro quella vera (tratteggiata)'], ['Basi', 'le singole basi moltiplicate per i coefficienti: la loro somma è la curva'], ['Variabilità', 'il fascio delle stime sui campioni precedenti'], ['Compromesso', 'distorsione², varianza ed errore in funzione dei gradi di libertà, e il minimo indicato dalla validazione incrociata']],
    tabella: 'Tutti i valori teorici sono esatti, perché i quattro metodi sono lisciatori lineari ŷ = Sy: distorsione² = ‖Sf − f‖²/n e varianza = σ² tr(SSᵀ)/n ai punti del disegno. L’ultima riga confronta l’errore teorico con quello medio osservato sui campioni simulati.',
    esempio: '<p><strong>Esempio svolto.</strong> Con una spline di regressione a 8 basi la matrice S è una proiezione: tr(S) = 8 e la varianza media vale esattamente σ²·8/n. Con σ = 0,3 e n = 100: 0,09·8/100 = 0,0072. Raddoppiando le basi la varianza raddoppia; la distorsione diminuisce solo finché la curva vera ha dettagli da catturare.</p>',
    errori: ['Scegliere il numero di basi guardando solo l’adattamento ai dati (che migliora sempre)', 'Usare un polinomio di grado alto: oscilla ai bordi (fenomeno di Runge)', 'Confrontare metodi diversi a parità di parametro anziché di gradi di libertà effettivi', 'Estrapolare una spline fuori dall’intervallo osservato'],
    avanzato: '<h3>Modelli additivi</h3><p>Con più predittori si stima y = β₀ + f₁(x₁) + f₂(x₂) + … con una spline penalizzata per ciascuna funzione: sono i GAM (<code>mgcv::gam</code>), con la scelta di λ per REML o GCV.</p><h3>Spline naturali e nodi</h3><p>Le spline naturali impongono linearità oltre i nodi estremi, riducendo la varianza ai bordi. Con le P-spline il numero di nodi conta poco purché sia abbondante: la complessità la decide λ.</p><h3>Interpretazione mista</h3><p>Una spline penalizzata equivale a un modello lineare misto in cui i coefficienti penalizzati sono effetti casuali: λ = σ²/σ<sub>b</sub>² e si stima per massima verosimiglianza ristretta.</p>',
    esercizi: [['Perché per una spline di regressione tr(S) è uguale al numero di basi?', 'S = B(BᵀB)⁻¹Bᵀ è una proiezione sullo spazio delle basi: la sua traccia è la dimensione di quello spazio.'], ['Che cosa succede alla P-spline per λ → ∞ con penalità sulle differenze seconde?', 'I coefficienti diventano lineari nell’indice e la curva tende alla retta dei minimi quadrati (2 gradi di libertà).'], ['Perché la validazione incrociata stima errore − σ²?', 'L’errore di previsione su un nuovo punto è σ² più l’errore di stima della curva: sottraendo σ² resta l’errore sulla curva.']],
    riferimenti: ['Hastie T., Tibshirani R., Friedman J. (2009). The Elements of Statistical Learning, 2ª ed. Springer, capp. 5–6.', 'Eilers P. H. C., Marx B. D. (1996). Flexible smoothing with B-splines and penalties. Statistical Science 11, 89–121.', 'Wood S. N. (2017). Generalized Additive Models: An Introduction with R, 2ª ed. CRC Press.', 'Wand M. P., Jones M. C. (1995). Kernel Smoothing. Chapman & Hall.']
  },
  segmentata: {
    obiettivi: ['Specificare e interpretare un modello lineare a tratti con breakpoint', 'Stimare il breakpoint profilando la somma dei quadrati dei residui', 'Riconoscere la non identificabilità quando il cambiamento non esiste', 'Verificare l’esistenza del cambiamento con un test che tenga conto di ψ ignoto'],
    valutiamo: [['Stima del breakpoint', 'il minimo del profilo RSS(ψ) e la spezzata stimata'], ['Incertezza', 'la larghezza della zona piatta del profilo e la dispersione di ψ̂ nei campioni ripetuti'], ['Identificabilità', 'con δ = 0 le stime di ψ si spargono e si accumulano sui bordi della griglia'], ['Utilità predittiva', 'l’errore sulla funzione media di retta, segmentata e spline']],
    tabella: 'Le pendenze sono le stime del campione corrente. Le righe Monte Carlo riassumono ψ̂ su tutti i campioni simulati: media, distorsione, RMSE e quota di stime sul bordo della griglia. L’insieme plausibile del profilo è indicativo, perché l’inferenza su ψ non è regolare; il test di esistenza è un bootstrap parametrico sotto H₀ che ripete anche la ricerca di ψ.',
    esempio: '<p><strong>Esempio svolto.</strong> Con β₁ = 0,5, δ = 1,2 e ψ = 6 la pendenza passa da 0,5 a 1,7. Il segnale |δ|/σ = 1,2 con n = 80 basta a concentrare ψ̂ attorno a 6; con δ = 0,3 la distribuzione di ψ̂ si allarga su quasi tutto l’intervallo, e con δ = 0 le stime cadono ovunque, molte ai bordi: lì ψ non esiste.</p>',
    errori: ['Riportare un intervallo di Wald per ψ come se avesse copertura nominale', 'Testare δ = 0 con il test F classico dopo aver scelto ψ sui dati', 'Cercare breakpoint molto vicini agli estremi delle x, dove restano poche osservazioni', 'Interpretare un breakpoint stimato come prova di un cambiamento reale'],
    avanzato: '<h3>Più breakpoint</h3><p>Con k breakpoint la ricerca su griglia diventa k-dimensionale; si usano algoritmi iterativi (Muggeo) o programmazione dinamica (Bai e Perron, per le serie temporali), e criteri come BIC per scegliere k.</p><h3>Modelli con salto</h3><p>Se la media è discontinua in ψ (cambio di livello), la stima di ψ converge con velocità n anziché √n, ma la sua legge limite non è normale: anche gli intervalli bootstrap standard possono fallire.</p><h3>Bootstrap sotto l’ipotesi nulla</h3><p>Per calibrare sup<sub>ψ</sub> della statistica si simulano dati dal modello nullo stimato e su ciascuno si ripete l’intera procedura, inclusa la ricerca di ψ: è il punto che rende il test valido.</p>',
    esercizi: [['Perché per ψ fissato il modello è lineare?', 'Il termine (x − ψ)₊ è una variabile nota quando ψ è noto: il modello è lineare in (β₀, β₁, δ).'], ['Con δ = 0, che cosa succede alla funzione RSS(ψ) in media?', 'È piatta a meno di fluttuazioni: ogni ψ produce la stessa retta vera, quindi il minimo dipende solo dal rumore.'], ['Perché si escludono i candidati vicini ai bordi?', 'Da un lato resterebbero pochissimi punti: la pendenza di quel tratto sarebbe stimata male e il minimo di RSS cadrebbe lì spesso per caso.']],
    riferimenti: ['Muggeo V. M. R. (2003). Estimating regression models with unknown break-points. Statistics in Medicine 22, 3055–3071.', 'Muggeo V. M. R. (2008). segmented: an R package to fit regression models with broken-line relationships. R News 8(1), 20–25.', 'Davies R. B. (1987). Hypothesis testing when a nuisance parameter is present only under the alternative. Biometrika 74, 33–43.', 'Feder P. I. (1975). On asymptotic distribution theory in segmented regression problems — identified case. Annals of Statistics 3, 49–83.']
  },
  validazione: {
    obiettivi: ['Distinguere errore di training, errore sul test ed errore di generalizzazione', 'Scegliere la complessità con la validazione incrociata a K fold', 'Riconoscere l’ottimismo di una valutazione che usa il test per scegliere', 'Organizzare un protocollo senza leakage: suddivisione, selezione, stima finale'],
    valutiamo: [['Errore di training', 'scende sempre aumentando il grado: misura l’adattamento, non la previsione'], ['Errore di generalizzazione', 'Err(d) = σ² + E(f(X) − f̂(X))², calcolato sulla funzione vera'], ['Selezione', 'il grado scelto dalla validazione incrociata e la sua variabilità tra repliche'], ['Onestà della stima', 'distorsione dell’errore sul test con protocollo corretto e con scelta sul test']],
    tabella: 'Err(d) è l’errore atteso su un nuovo punto per il modello stimato, calcolato con la funzione vera e una quadratura su 200 punti (badge approssimato). Le righe Monte Carlo confrontano, su tutte le repliche, la stima dell’errore riportata da ciascun protocollo con l’errore vero del modello che quel protocollo ha scelto: la differenza media è la distorsione del protocollo.',
    esempio: '<p><strong>Esempio svolto.</strong> Con f(x) = sin(2πx), σ = 0,3, n = 60 e 18 punti di test, l’errore di training al grado 12 vale in media 0,062, cioè σ²(1 − 13/42): meno dell’errore irriducibile σ² = 0,09. L’errore vero dello stesso polinomio, invece, esplode (in media oltre 30) per le oscillazioni vicino ai bordi, dove i dati sono pochi. La validazione incrociata a 5 fold sceglie quasi sempre un grado tra 3 e 7. Se invece si sceglie il grado con l’errore sul test più basso e si riporta quell’errore, la stima risulta in media più bassa dell’errore vero: è l’ottimismo della selezione.</p>',
    errori: ['Scegliere il modello guardando l’errore sul test e poi riportare quello stesso errore', 'Standardizzare o selezionare variabili su tutti i dati prima di dividerli (leakage)', 'Leggere il grado scelto dalla CV come “vero” grado del modello', 'Confondere l’errore stimato dalla CV (atteso) con l’errore del modello effettivamente stimato (condizionato)'],
    avanzato: '<h3>Validazione incrociata annidata</h3><p>Quando la selezione è parte del metodo, per valutarlo serve un ciclo esterno: in ogni fold esterno si ripete l’intera selezione (CV interna) sui soli dati di training e si misura l’errore sul fold esterno. Così la stima finale non è contaminata dalla scelta.</p><h3>Che cosa stima la CV</h3><p>Bates, Hastie e Tibshirani (2024) mostrano che la CV stima bene l’errore <em>atteso</em> sui possibili insiemi di training, non quello del modello stimato sui dati in mano; gli intervalli “naïf” basati sulla varianza tra fold sono troppo stretti.</p><h3>Ottimismo</h3><p>Per un lisciatore lineare con x fissi, l’errore atteso in-sample supera quello di training di 2σ²·df/n (Efron, 2004): è la base di Cp, AIC e GCV, alternative analitiche alla CV.</p>',
    esercizi: [['Perché l’errore di training non può aumentare con il grado del polinomio?', 'I modelli sono annidati: un polinomio di grado d+1 contiene quelli di grado d, quindi il minimo della somma dei quadrati non può crescere.'], ['Perché, condizionatamente al modello stimato, l’errore sul test è non distorto per Err?', 'I punti di test sono indipendenti dal training e mai usati per decidere: ogni errore al quadrato ha media Err, quindi anche la loro media.'], ['Con K = n (leave-one-out) che cosa si guadagna e che cosa si perde?', 'Ogni modello usa n − 1 osservazioni (distorsione piccola) ma i modelli sono quasi identici: la stima può avere varianza alta, e il costo è n stime (salvo forme chiuse, come nel lab 16).']],
    riferimenti: ['Hastie T., Tibshirani R., Friedman J. (2009). The Elements of Statistical Learning, 2ª ed. Springer, cap. 7.', 'James G., Witten D., Hastie T., Tibshirani R. (2021). An Introduction to Statistical Learning, 2ª ed. Springer, cap. 5.', 'Bates S., Hastie T., Tibshirani R. (2024). Cross-validation: what does it estimate and how well does it do it? Journal of the American Statistical Association 119, 1434–1445.', 'Varma S., Simon R. (2006). Bias in error estimation when using cross-validation for model selection. BMC Bioinformatics 7, 91.']
  },
  knn: {
    obiettivi: ['Descrivere la regola dei k vicini come stima locale di P(Y = 1 | x)', 'Confrontare l’errore del kNN con l’errore di Bayes', 'Scegliere k con la validazione leave-one-out', 'Riconoscere l’effetto delle unità di misura e standardizzare senza leakage'],
    valutiamo: [['Frontiera', 'le regioni kNN contro la frontiera di Bayes, al variare di k'], ['Errore', 'training, leave-one-out e test in funzione di k, con l’errore di Bayes come limite'], ['Qualità della classificazione', 'accuratezza, sensibilità e specificità con intervalli di Wilson'], ['Scala', 'che cosa succede alle distanze se una variabile ha unità 10 volte più grandi']],
    tabella: 'L’errore di Bayes è esatto perché le leggi delle classi sono note. Le righe della replica corrente usano 500 punti di test nuovi con intervalli di Wilson al 95%; le righe Monte Carlo mediano su tutte le repliche. Con k = 1 e n → ∞ l’errore tende a E[2η(1 − η)] (calcolato per quadratura), che Cover e Hart limitano con 2R*(1 − R*).',
    esempio: '<p><strong>Esempio svolto.</strong> Nello scenario lineare con δ = 2 l’errore di Bayes è Φ(−1) = 0,159. Con k = 1 e n = 100 l’errore di training è 0 e quello sul test circa 0,235: già vicino al suo limite per n → ∞, E[2η(1 − η)], pari a 0,225 e mai oltre 2 · 0,159 · 0,841 = 0,267 (Cover e Hart). Con k tra 15 e 35 l’errore sul test scende a circa 0,175: ascoltare più vicini riduce la varianza.</p>',
    errori: ['Valutare il kNN sul training: con k = 1 l’errore è sempre 0', 'Calcolare distanze su variabili con unità di misura molto diverse', 'Standardizzare con medie e sd di tutti i dati, test compreso', 'Usare k pari con due classi senza una regola per le parità'],
    avanzato: '<h3>Pesi e metriche</h3><p>I vicini possono votare con peso decrescente nella distanza; la metrica può essere adattata ai dati (Mahalanobis, metric learning). Con molte variabili irrilevanti il kNN peggiora rapidamente: selezione o riduzione delle dimensioni (lab 21) aiutano.</p><h3>Stima della probabilità</h3><p>La quota di voti p̂(x) è uno stimatore della probabilità condizionata: distorto quando k è grande rispetto alla curvatura di P(Y = 1 | x), variabile quando k è piccolo. Lo stesso compromesso del lisciamento nel lab 16.</p><h3>Classi sbilanciate</h3><p>Se una classe è rara, la maggioranza dei vicini tende a ignorarla: si spostano le soglie o si pesano le classi, e si guardano sensibilità e specificità oltre all’accuratezza.</p>',
    esercizi: [['Perché con k = n − 1 (leave-one-out) il kNN prevede quasi sempre la stessa classe?', 'Tutti gli altri punti votano: la previsione è la classe più frequente nel training, tranne l’effetto di aver escluso il punto stesso.'], ['Nello scenario lineare, perché la frontiera di Bayes è x₁ = 0 anche se x₂ è moltiplicata per 10?', 'x₂ ha la stessa legge nelle due classi: non contiene informazione, e cambiarne la scala non sposta la frontiera. Sposta però le distanze del kNN.'], ['Perché la stima leave-one-out per il kNN è “gratuita”?', 'Non c’è un modello da ristimare: basta escludere il punto dall’elenco dei suoi vicini.']],
    riferimenti: ['Cover T. M., Hart P. E. (1967). Nearest neighbor pattern classification. IEEE Transactions on Information Theory 13, 21–27.', 'Stone C. J. (1977). Consistent nonparametric regression. Annals of Statistics 5, 595–645.', 'Hastie T., Tibshirani R., Friedman J. (2009). The Elements of Statistical Learning, 2ª ed. Springer, capp. 2 e 13.', 'James G., Witten D., Hastie T., Tibshirani R. (2021). An Introduction to Statistical Learning, 2ª ed. Springer, cap. 4.']
  },
  alberi: {
    obiettivi: ['Costruire un albero di classificazione con l’impurità di Gini', 'Riconoscere l’instabilità di un albero profondo', 'Spiegare come bagging e foresta casuale riducono la varianza', 'Usare l’errore out-of-bag come stima dell’errore di previsione'],
    valutiamo: [['Instabilità', 'quanto cambia l’albero passando dai dati a un campione bootstrap'], ['Aggregazione', 'l’errore sul test di un albero, del bagging e della foresta al crescere degli alberi'], ['Decorrelazione', 'quanto spesso gli alberi concordano e quale variabile scelgono nella radice'], ['Stima OOB', 'quanto l’errore out-of-bag segue l’errore sul test']],
    tabella: 'L’errore di Bayes è esatto: la regola migliore è il segno di g(x) e le etichette sono scambiate con probabilità ε indipendentemente da x. Gli errori sul test usano 1000 punti nuovi con intervallo di Wilson; l’accordo tra alberi e la variabile della radice sono medie sugli alberi costruiti.',
    esempio: '<p><strong>Esempio svolto.</strong> Con il cerchio, n = 200, ε = 0,1 e tre variabili di rumore, un albero senza limiti di profondità sbaglia sul test circa una volta su cinque (0,22). Cento alberi di bagging scendono verso 0,18, la foresta con mtry = 2 un po’ più in basso. L’accordo medio tra coppie di alberi è più basso nella foresta: è proprio la decorrelazione che rende efficace la media.</p>',
    errori: ['Leggere un singolo albero profondo come “il” modello dei dati', 'Calcolare l’errore OOB includendo alberi che hanno visto l’osservazione', 'Aspettarsi che aggiungere alberi riduca l’errore all’infinito', 'Confondere mtry = p (bagging) con una foresta casuale'],
    avanzato: '<h3>Potatura</h3><p>Un singolo albero si controlla con la potatura per costo-complessità: si cresce un albero grande e si tagliano i rami che riducono poco l’errore, scegliendo il parametro con la validazione incrociata (<code>rpart</code>, parametro cp).</p><h3>Boosting</h3><p>Invece di mediare alberi indipendenti, il boosting costruisce alberi piccoli in sequenza, ciascuno sui residui del precedente: riduce soprattutto la distorsione e richiede una scelta attenta del numero di passi.</p><h3>Probabilità e calibrazione</h3><p>La quota di alberi che votano 1 non è una probabilità calibrata: per stimare P(Y = 1 | x) si usano foreste di probabilità o una calibrazione successiva.</p>',
    esercizi: [['Perché la riduzione di Gini di una divisione accettata è sempre positiva?', 'Il Gini è concavo nella proporzione: il Gini pesato dei figli non supera quello del padre, e qui si accettano solo divisioni con riduzione strettamente positiva.'], ['Quale frazione di osservazioni resta fuori da un campione bootstrap?', '(1 − 1/n)ⁿ, che tende a e⁻¹ ≈ 0,368.'], ['Perché con mtry = 1 e molte variabili di rumore la foresta può peggiorare?', 'A molti nodi l’unica candidata è una variabile di rumore: la divisione non porta informazione e gli alberi diventano deboli, anche se poco correlati.']],
    riferimenti: ['Breiman L., Friedman J., Olshen R., Stone C. (1984). Classification and Regression Trees. Wadsworth.', 'Breiman L. (1996). Bagging predictors. Machine Learning 24, 123–140.', 'Breiman L. (2001). Random forests. Machine Learning 45, 5–32.', 'Hastie T., Tibshirani R., Friedman J. (2009). The Elements of Statistical Learning, 2ª ed. Springer, capp. 9, 15.']
  },
  pca: {
    obiettivi: ['Definire componenti principali, autovalori e score a partire dalla matrice di covarianza', 'Leggere scree plot, varianza spiegata e biplot', 'Collegare il numero di componenti all’errore di ricostruzione', 'Valutare stabilità degli assi, segni arbitrari, autovalori ripetuti e scelta della standardizzazione'],
    valutiamo: [['Assi', 'le direzioni stimate rispetto a quelle della popolazione'], ['Varianza spiegata', 'le quote per componente e la cumulata'], ['Ricostruzione', 'quanto si perde tenendo k componenti'], ['Stabilità', 'l’angolo tra PC1 stimata e vera nei campioni ripetuti, contro la teoria asintotica']],
    tabella: 'Le quote della popolazione sono esatte (autovalori di Σ o della matrice di correlazione). L’identità tra errore di ricostruzione e autovalori scartati vale in ogni campione. Media e deviazione standard di λ̂₁ e il sin² medio dell’angolo si confrontano con l’asintotica di Anderson, valida per dati normali, PCA sulla covarianza e λ₁ > λ₂.',
    esempio: '<p><strong>Esempio svolto.</strong> Con p = 2, λ₁ = 4, λ₂ = 1 la prima componente spiega 4/5 = 80% della varianza. L’asintotica dà E[sin²θ] ≈ λ₁λ₂/((λ₁ − λ₂)² n) = 4/(9 · 80) ≈ 0,0056, cioè un angolo tipico di circa 4°. Con λ₁ = 1,5 lo stesso calcolo dà 1,5/(0,25 · 80) = 0,075: circa 16°, e l’asse stimato oscilla molto. Con λ₁ = λ₂ l’asse non è identificato.</p>',
    errori: ['Interpretare il segno di un loading come un’informazione', 'Fare la PCA su variabili con unità molto diverse senza chiedersi se standardizzare', 'Leggere i primi assi come gruppi o come direzioni utili per prevedere', 'Confrontare singoli autovettori quando gli autovalori sono quasi uguali'],
    avanzato: '<h3>SVD</h3><p>Z = UDVᵀ: le colonne di V sono gli assi, gli score sono UD e λⱼ = dⱼ²/(n − 1). È il modo numericamente più stabile (lo usa <code>prcomp</code>), e funziona anche con p &gt; n.</p><h3>Quante componenti</h3><p>Scree plot (gomito), soglia sulla varianza cumulata, analisi parallela (confronto con autovalori di dati casuali) o validazione incrociata della ricostruzione: nessun criterio è universale.</p><h3>Varianti</h3><p>PCA robusta (meno sensibile ai valori anomali), sparse PCA (loading con molti zeri, più interpretabili), PCA probabilistica e analisi fattoriale (con un modello per l’errore).</p>',
    esercizi: [['Perché la somma degli autovalori è uguale alla somma delle varianze delle variabili?', 'La traccia è invariante per cambi di base ortonormale: tr(S) = tr(VΛVᵀ) = Σ λⱼ.'], ['Perché gli score delle diverse componenti sono incorrelati?', 'TᵀT/(n − 1) = VᵀSV = Λ, che è diagonale.'], ['Che cosa succede alla PCA sulla correlazione se si moltiplica una variabile per 10?', 'Nulla: la matrice di correlazione non cambia. Cambia invece quella sulla covarianza.']],
    riferimenti: ['Jolliffe I. T. (2002). Principal Component Analysis, 2ª ed. Springer.', 'Anderson T. W. (1963). Asymptotic theory for principal component analysis. Annals of Mathematical Statistics 34, 122–148.', 'Jolliffe I. T., Cadima J. (2016). Principal component analysis: a review and recent developments. Philosophical Transactions of the Royal Society A 374, 20150202.', 'James G., Witten D., Hastie T., Tibshirani R. (2021). An Introduction to Statistical Learning, 2ª ed. Springer, cap. 12.']
  },
  clustering: {
    obiettivi: ['Descrivere k-means come minimizzazione della WCSS e l’algoritmo di Lloyd', 'Riconoscere minimi locali e il ruolo dei centri iniziali e dei riavvii', 'Costruire e leggere un dendrogramma con legami diversi', 'Confrontare partizioni con misure invarianti alle etichette'],
    valutiamo: [['Lloyd', 'assegnazione e aggiornamento, e la WCSS che non cresce mai'], ['Minimi locali', 'quante soluzioni diverse producono avvii diversi'], ['Legami', 'come cambia il dendrogramma con Ward, completo, medio e singolo'], ['Gruppi veri e trovati', 'l’indice di Rand corretto rispetto alle popolazioni generatrici']],
    tabella: 'Le proprietà garantite (WCSS monotona, n − 1 fusioni, altezze non decrescenti, invarianza alle etichette) sono verificate sui dati correnti. Le righe sugli avvii riassumono le soluzioni di k-means; l’ARI confronta le partizioni con le popolazioni che hanno generato i dati, note solo perché i dati sono simulati.',
    esempio: '<p><strong>Esempio svolto.</strong> Con tre popolazioni sferiche a distanza d = 3 e K = 3, la soluzione migliore tra dieci avvii ha ARI 0,96, ma alcuni avvii si fermano in minimi locali con WCSS tre volte più grande. Con popolazioni allungate k-means taglia i gruppi per traverso e l’ARI scende a circa 0,76. Con d = 1 i gruppi si sovrappongono: l’algoritmo restituisce comunque tre gruppi, che però non corrispondono alle popolazioni.</p>',
    errori: ['Fidarsi di un solo avvio di k-means', 'Confrontare partizioni guardando i numeri dei gruppi', 'Usare k-means su variabili con scale molto diverse senza standardizzare', 'Leggere i gruppi trovati come prova che i gruppi esistono'],
    avanzato: '<h3>Modelli di miscuglio</h3><p>k-means è il limite di un miscuglio di normali sferiche con la stessa varianza, stimato con un algoritmo EM “duro”. I miscugli gaussiani (<code>mclust</code>) ammettono forme ed estensioni diverse e scelgono K con il BIC.</p><h3>Legame singolo e catene</h3><p>Il legame singolo coincide con l’albero ricoprente minimo: individua gruppi di forma qualunque ma unisce gruppi separati da un ponte di pochi punti (effetto catena).</p><h3>Stabilità</h3><p>Ricampionando i dati (bootstrap) e confrontando le partizioni con l’ARI si misura quanto un raggruppamento è stabile: gruppi instabili vanno interpretati con cautela.</p>',
    esercizi: [['Perché il passo di aggiornamento non può aumentare la WCSS?', 'Per un gruppo fisso, la media è il punto che rende minima la somma dei quadrati delle distanze.'], ['Che cosa succede alla WCSS minima aumentando K?', 'Non cresce mai: con K + 1 centri si può sempre riprodurre la soluzione con K e fare almeno altrettanto bene. Con K = n è zero.'], ['Perché due partizioni identiche con numeri dei gruppi scambiati hanno ARI = 1?', 'L’ARI conta coppie di osservazioni nello stesso gruppo o in gruppi diversi, e queste coppie non dipendono dai nomi dei gruppi.']],
    riferimenti: ['Lloyd S. P. (1982). Least squares quantization in PCM. IEEE Transactions on Information Theory 28, 129–137.', 'Hubert L., Arabie P. (1985). Comparing partitions. Journal of Classification 2, 193–218.', 'Murtagh F., Legendre P. (2014). Ward’s hierarchical agglomerative clustering method: which algorithms implement Ward’s criterion? Journal of Classification 31, 274–295.', 'Kaufman L., Rousseeuw P. J. (1990). Finding Groups in Data. Wiley.']
  },
  dbscan: {
    obiettivi: ['Definire punti core, di bordo e rumore a partire da ε e minPts', 'Seguire la costruzione di un cluster per espansione della densità', 'Scegliere ε con il grafico delle k-distanze e valutarne la sensibilità', 'Confrontare DBSCAN, k-means e Ward su forme non sferiche e densità diverse'],
    valutiamo: [['Densità', 'quali punti sono core, bordo o rumore'], ['Forma', 'se un metodo segue lune e cerchi o li taglia'], ['Parametri', 'come ARI e quota di rumore cambiano con ε'], ['Rumore', 'quanti punti anomali generati vengono riconosciuti come tali']],
    tabella: 'Le classi vere sono note perché i dati sono simulati: gli anomali sono un gruppo a parte e il rumore di DBSCAN conta come un gruppo nel calcolo dell’ARI. La silhouette di DBSCAN esclude i punti di rumore. I controlli verificano le definizioni e che l’animazione coincida con la procedura di riferimento.',
    esempio: '<p><strong>Esempio svolto.</strong> Sulle due lune con 10 punti anomali, ε = 0,2 e minPts = 5, DBSCAN trova le due lune (ARI 0,99) e mette in rumore 8 dei 10 anomali; k-means e Ward con K = 2 tagliano le lune con una linea (ARI 0,16 e 0,33). Con n = 600 la densità raddoppia e lo stesso ε fonde le lune in un solo cluster: ε va riletto quando cambia n. Con i tre gruppi di densità diversa nessun ε va bene per tutti: il gruppo diffuso si spezza o i gruppi compatti si fondono con il rumore.</p>',
    errori: ['Scegliere ε senza guardare la scala delle variabili', 'Interpretare il rumore come “errore” da eliminare senza verificarlo', 'Usare la silhouette per giudicare cluster non convessi', 'Credere che i punti di bordo abbiano un’assegnazione univoca'],
    avanzato: '<h3>HDBSCAN e OPTICS</h3><p>Invece di fissare ε, ordinano i punti per raggiungibilità e costruiscono una gerarchia di cluster al variare della densità; HDBSCAN estrae i cluster più stabili lungo la gerarchia ed è robusto a densità diverse.</p><h3>Complessità</h3><p>La parte costosa è trovare gli intorni: O(n²) con il calcolo diretto, circa O(n log n) con alberi k-d in poche dimensioni (pacchetto <code>dbscan</code>).</p><h3>Molte dimensioni</h3><p>In alta dimensione le distanze si concentrano e la nozione di densità perde contrasto: conviene ridurre prima la dimensione (lab 21) o scegliere metriche adatte ai dati.</p>',
    esercizi: [['Perché un punto core non può essere rumore?', 'Ha almeno minPts punti nel suo intorno: è il seme di un cluster, e l’algoritmo lo assegna quando lo visita.'], ['Con minPts = 1, che cosa diventa DBSCAN?', 'Ogni punto è core: i cluster sono le componenti connesse del grafo ε e non c’è rumore.'], ['Perché un punto di bordo può cambiare cluster riordinando i dati?', 'Se è nell’intorno di core di due cluster diversi, viene assegnato al primo cluster che lo raggiunge, e l’ordine di visita dipende dall’ordine dei dati.']],
    riferimenti: ['Ester M., Kriegel H.-P., Sander J., Xu X. (1996). A density-based algorithm for discovering clusters in large spatial databases with noise. KDD-96, 226–231.', 'Schubert E., Sander J., Ester M., Kriegel H.-P., Xu X. (2017). DBSCAN revisited, revisited. ACM Transactions on Database Systems 42, 19.', 'Campello R. J. G. B., Moulavi D., Sander J. (2013). Density-based clustering based on hierarchical density estimates. PAKDD 2013, 160–172.', 'Hahsler M., Piekenbrock M., Doran D. (2019). dbscan: fast density-based clustering with R. Journal of Statistical Software 91(1).']
  },
  'reti-neurali': {
    obiettivi: ['Descrivere una rete con uno strato nascosto: pesi, attivazioni, uscita sigmoide', 'Calcolare il gradiente con la backpropagation e verificarlo con le differenze finite', 'Riconoscere gli effetti del learning rate, della penalità L2 e del numero di neuroni', 'Distinguere errore di training e di validazione, e valutare l’effetto dell’inizializzazione'],
    valutiamo: [['Frontiera', 'come la regione di classificazione si piega durante l’addestramento'], ['Gradiente', 'gli errori δ propagati all’indietro e il controllo con differenze finite'], ['Addestramento', 'perdita di training e validazione epoca per epoca, divergenza con η alto'], ['Inizializzazione', 'esiti di venti partenze diverse sugli stessi dati']],
    tabella: 'Il numero di parametri e il controllo del gradiente sono verifiche esatte. Perdite e accuratezze si riferiscono all’epoca corrente; con p = 0,5 ovunque la perdita vale log 2 ≈ 0,693, il riferimento di una rete che non ha imparato nulla. La riga sulle inizializzazioni riassume venti addestramenti completi sugli stessi dati.',
    esempio: '<p><strong>Esempio svolto.</strong> Su XOR con H = 4, tanh e η = 1, dopo 2000 epoche la perdita di training scende da 0,80 a 0,17 e l’accuratezza di validazione arriva a 0,88 (il rumore σ = 0,1 sposta alcuni punti oltre gli assi). Con η = 30 la perdita sale invece di scendere; con H = 2 solo 4 inizializzazioni su 20 superano 0,9 in validazione: le altre si fermano in soluzioni che separano bene solo parte dei quadranti. Con H = 8, poco rumore e n = 60 la validazione smette di migliorare molto prima del training.</p>',
    errori: ['Giudicare la rete dall’accuratezza di training', 'Usare un learning rate alto per “fare prima”', 'Considerare definitivo il risultato di una sola inizializzazione', 'Confondere il numero di parametri con la complessità effettiva della funzione appresa'],
    avanzato: '<h3>Ottimizzatori</h3><p>Il gradiente stocastico (mini-batch) aggiunge rumore che aiuta a uscire dalle zone piatte; il momento e Adam adattano direzione e lunghezza del passo. Cambiano il percorso e spesso la soluzione finale.</p><h3>Reti profonde</h3><p>Con più strati il gradiente può svanire o esplodere (soprattutto con sigmoide e tanh); ReLU, inizializzazioni scalate e normalizzazione dei lotti rendono addestrabili reti molto profonde.</p><h3>Doppia discesa</h3><p>Aumentando molto il numero di parametri, l’errore di test può risalire vicino al punto in cui la rete interpola i dati e poi scendere di nuovo: il compromesso distorsione–varianza classico non descrive sempre i modelli sovraparametrizzati.</p>',
    esercizi: [['Perché con tutti i pesi iniziali uguali a zero la rete non impara nulla di utile?', 'Tutti i neuroni nascosti calcolano la stessa funzione e ricevono lo stesso gradiente: restano identici a ogni passo (simmetria non rotta).'], ['Quanti parametri ha una rete 2 → H → 1?', '2H pesi in ingresso, H intercette nascoste, H pesi in uscita e un’intercetta: 4H + 1.'], ['Perché la BCE si calcola da z e non da p?', 'Per z grandi p si arrotonda a 0 o 1 e log p diventa −∞; la forma max(z, 0) − yz + log(1 + e^−|z|) resta finita e precisa.']],
    riferimenti: ['Rumelhart D. E., Hinton G. E., Williams R. J. (1986). Learning representations by back-propagating errors. Nature 323, 533–536.', 'Goodfellow I., Bengio Y., Courville A. (2016). Deep Learning. MIT Press, capp. 6–8.', 'Glorot X., Bengio Y. (2010). Understanding the difficulty of training deep feedforward neural networks. AISTATS 2010, 249–256.', 'Hastie T., Tibshirani R., Friedman J. (2009). The Elements of Statistical Learning, 2ª ed. Springer, cap. 11.']
  }
};
